def retry(n):
    def deco(fn):
        def inner(*a,**k):
            last=None
            for _ in range(n):
                try: return fn(*a,**k)
                except Exception as e: last=e
            raise last
        return inner
    return deco

def dups(xs):
    s,d=set(),set()
    for x in xs:
        (d if x in s else s).add(x)
    return list(d)

from collections import Counter
def first_uniq(s):
    c=Counter(s)
    for ch in s:
        if c[ch]==1: return ch

from collections import OrderedDict
class LRU:
    def __init__(s,n): s.n,s.d=n,OrderedDict()
    def get(s,k):
        if k not in s.d: return None
        s.d.move_to_end(k); return s.d[k]
    def put(s,k,v):
        s.d[k]=v; s.d.move_to_end(k)
        if len(s.d)>s.n: s.d.popitem(last=False)
